-- fdh-c-check: ip row count of IRF
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT COUNT(*) AS n FROM p JOIN ipt a ON a.dchdate BETWEEN p.s AND p.e INNER JOIN referout ro ON ro.vn = a.an WHERE TRIM(COALESCE(ro.refer_hospcode, ro.hospcode, '')) NOT IN ('', (SELECT hospitalcode FROM opdconfig LIMIT 1));
